import{_ as d,o as r,c as e,a6 as n}from"./chunks/framework.B_q3ZJNF.js";const _=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"nginx-internals-course/glossary.md","filePath":"nginx-internals-course/docs/glossary.md"}'),o={name:"nginx-internals-course/glossary.md"};function a(s,t,i,l,c,p){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书术语按首现顺序收录，定义就是正文首现时那句人话——忘了哪个词，回这里查。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话定义</th></tr></thead><tbody><tr><td>并发连接数</td><td>concurrent connections</td><td>同一时刻挂在服务器上的「通话中」数量，不是每秒新来电数</td></tr><tr><td>C10K 问题</td><td>C10K problem</td><td>一台服务器同时伺候一万个连接这道经典难题</td></tr><tr><td>套接字</td><td>socket</td><td>程序世界里的一部电话机——应用程序通过它接进网络打电话</td></tr><tr><td>文件描述符</td><td>file descriptor</td><td>操作系统发给每个「电话机」的编号凭条</td></tr><tr><td>阻塞 I/O</td><td>blocking I/O</td><td>打电话时占着人死等对方开口，别的什么都干不了</td></tr><tr><td>非阻塞 I/O</td><td>non-blocking I/O</td><td>不占人死等——留一句「有消息叫我」，自己继续干别的</td></tr><tr><td>事件多路复用</td><td>I/O multiplexing</td><td>雇一位传达室大爷同时盯一万个门铃，谁响了叫谁来取</td></tr><tr><td>epoll</td><td>—</td><td>Linux 提供的那位「传达室大爷」的官方名字</td></tr><tr><td>事件循环</td><td>event loop</td><td>不断重复「等事件→处理事件」的循环，服务器的心跳</td></tr><tr><td>回调</td><td>callback</td><td>留给系统的一句留言：「事来了打这个电话」</td></tr><tr><td>TCP 连接</td><td>TCP connection</td><td>两个程序之间拨通的通话线路，保证字节按序完整到达</td></tr><tr><td>字节流</td><td>byte stream</td><td>数据在网络里像水管的水，一股股涌出来，天生不分「一封一封」</td></tr><tr><td>粘包与半包</td><td>—</td><td>一次到货粘了两条消息 / 一条消息只到一半——水管流水的常态</td></tr><tr><td>状态机</td><td>state machine</td><td>给解析器画的一张「读到哪了」地图，每读一段就知道下一步去哪</td></tr><tr><td>keep-alive</td><td>—</td><td>说完一件事不挂电话，接着说下一件</td></tr><tr><td>TIME_WAIT</td><td>—</td><td>主动挂电话的一方要原地多等一会儿才能走，防止最后的告别没送到</td></tr><tr><td>内存分配器</td><td>malloc</td><td>操作系统的「给我一块内存 / 我还一块内存」服务，每次记账都有成本</td></tr><tr><td>内存碎片</td><td>fragmentation</td><td>反复进货退货后，仓库里到处是塞不进大件的小空格</td></tr><tr><td>内存池</td><td>memory pool</td><td>整批进货再零售的仓库；清仓时整仓清空，不用一件件对账</td></tr><tr><td>配置上下文</td><td>context</td><td>nginx.conf 里一层层的花括号房间，指令写在哪个房间就算哪个房间的</td></tr><tr><td>配置继承</td><td>inheritance</td><td>房间没写的规矩沿用外面大房间的；写了就自己说了算</td></tr><tr><td>master 进程</td><td>—</td><td>只管不接待的老板：读配置、盯员工、收指令，不亲自伺候连接</td></tr><tr><td>worker 进程</td><td>—</td><td>真正伺候客人的员工，一人一摊互不打扰，倒了一个老板再招一个</td></tr><tr><td>信号</td><td>signal</td><td>操作系统层面发给进程的对讲机暗号</td></tr><tr><td>优雅关闭</td><td>graceful shutdown</td><td>「不再接新客，把手头客人送完再下班」</td></tr><tr><td>热升级</td><td>hot upgrade</td><td>换发动机不熄火——新二进制顶上，旧进程送完旧客才退</td></tr><tr><td>惊群</td><td>thundering herd</td><td>一窝蜂醒来抢同一个新连接，多数白忙一场（现代内核已解决）</td></tr><tr><td>反向代理</td><td>reverse proxy</td><td>站在真实服务器前面的前台接待员，客人只见前台</td></tr><tr><td>upstream</td><td>—</td><td>后台真正干活的服务器名单</td></tr><tr><td>负载均衡</td><td>load balancing</td><td>把活分给名单上几台服务器的分配规则</td></tr><tr><td>轮询</td><td>round robin</td><td>按名单顺序一家一个轮着来</td></tr><tr><td>故障转移</td><td>failover</td><td>一台坏了自动记下来、换下一台重试，别让客人看见失败</td></tr><tr><td>漏桶算法</td><td>leaky bucket</td><td>水先倒进固定漏斗、按固定速率漏出去；倒太猛直接溢出拒绝</td></tr><tr><td>突发余额</td><td>burst</td><td>漏斗上方临时加高的一段缓冲空间，偶尔倒猛点也不至于马上溢</td></tr><tr><td>缓冲</td><td>buffer</td><td>两个速度不一致的人之间摆的一张桌子，快的那方先把东西堆桌上</td></tr><tr><td>聚合写</td><td>writev</td><td>把几堆东西抱一次送出去，省得跑三趟</td></tr><tr><td>零拷贝</td><td>zero copy</td><td>货不进你家门：数据不搬到应用手里，从库房直接装车发走</td></tr><tr><td>sendfile</td><td>—</td><td>零拷贝在 Linux 上的官方通道——文件直接从磁盘送进网卡</td></tr><tr><td>慢速攻击</td><td>Slowloris</td><td>每条连接隔几秒发一个字节，拖住「攒完整包」服务器的内存</td></tr><tr><td>令牌桶</td><td>token bucket</td><td>漏桶的镜像：攒了令牌就能瞬时放行一批——限平均、允许攒突发</td></tr></tbody></table>',3)])])}const h=d(o,[["render",a]]);export{_ as __pageData,h as default};
